264	void TDRThread::run()
265	{
266	    qDebug() << "TDR thread starting";
267	    using namespace std::chrono;
268	    auto lastCalc = system_clock::now();
269	    while(1) {
270	        tdr.semphr.acquire();
271	        // clear possible additional semaphores
272	        tdr.semphr.tryAcquire(tdr.semphr.available());
273	        if(tdr.destructing) {
274	            // TDR object about to be deleted, exit thread
275	            qDebug() << "TDR thread exiting";
276	            return;
277	        }
278	        // qDebug() << "TDR thread calculating";
279	        // perform calculation
280	        if(!tdr.input) {
281	            // not connected, skip calculation
282	            continue;
283	        }
284	        auto inputData = tdr.input->getData();
285	        if(inputData.size() < 2) {
286	            // empty input data, clear output data
287	            tdr.clearOutput();
288	            tdr.warning("Not enough input samples");
289	            continue;
290	        }
291	        vector<complex<double>> frequencyDomain;
292	        auto stepSize = (inputData.back().x - inputData.front().x) / (inputData.size() - 1);
293	        if(tdr.mode == TDR::Mode::Lowpass) {
294	            auto steps = inputData.size();
295	            auto firstStep = inputData.front().x;
296	            // frequency points need to be evenly spaced all the way to DC
297	            if(firstStep == 0) {
298	                // zero as first step would result in infinite number of points, skip and start with second
299	                firstStep = inputData[1].x;
300	                steps--;
301	            }
302	            if(firstStep * steps != inputData.back().x) {
303	                // data is not available with correct frequency spacing, calculate required steps
304	                steps = inputData.back().x / firstStep;
305	                stepSize = firstStep;
306	            }
307	            frequencyDomain.resize(2 * steps + 1);
308	            // copy frequencies, use the flipped conjugate for negative part
309	            for(unsigned int i = 1;i<=steps;i++) {
310	                auto S = TraceMath::interpolatedSample(inputData, stepSize * i);
311	                frequencyDomain[steps - i] = conj(S);
312	                frequencyDomain[steps + i] = S;
313	            }
314	            if(tdr.automaticDC) {
315	                // use simple extrapolation from lowest two points to extract DC value
316	                auto abs_DC = 2.0 * abs(frequencyDomain[steps + 1]) - abs(frequencyDomain[steps + 2]);
317	                auto phase_DC = 2.0 * arg(frequencyDomain[steps + 1]) - arg(frequencyDomain[steps + 2]);
318	                frequencyDomain[steps] = polar(abs_DC, phase_DC);
319	            } else {
320	                frequencyDomain[steps] = tdr.manualDC;
321	            }
322	        } else {
323	            // bandpass mode
324	            // Can use input data directly, no need to extend with complex conjugate
325	            frequencyDomain.resize(inputData.size());
326	            for(unsigned int i=0;i<inputData.size();i++) {
327	                frequencyDomain[i] = inputData[i].y;
328	            }
329	        }
330	
331	        tdr.window.apply(frequencyDomain);
332	        tdr.unpaddedInputSize = frequencyDomain.size();
333	        if(tdr.padding > 0) {
334	            frequencyDomain.insert(frequencyDomain.begin(), tdr.padding/2, 0);
335	            frequencyDomain.insert(frequencyDomain.end(), tdr.padding/2, 0);
336	        }
337	        Fft::shift(frequencyDomain, true);
338	
339	        int fft_bins = frequencyDomain.size();
340	        const double fs = 1.0 / (stepSize * fft_bins);
341	
342	        Fft::transform(frequencyDomain, true);
343	        Fft::shift(frequencyDomain, false);
344	
345	        tdr.dataMutex.lock();
346	        tdr.data.resize(fft_bins, TraceMath::Data());
347	        for(int i = 0;i<fft_bins;i++) {
348	            tdr.data[i].x = fs * (i - fft_bins / 2);
349	            tdr.data[i].y = frequencyDomain[i] / (double) fft_bins;
350	        }
351	        auto size = tdr.data.size();
352	        tdr.dataMutex.unlock();
353	        if(tdr.stepResponse && tdr.mode == TDR::Mode::Lowpass) {
354	            tdr.updateStepResponse(true);
355	        } else {
356	            tdr.updateStepResponse(false);
357	        }
358	        emit tdr.outputSamplesChanged(0, size);
359	
360	        // limit update rate if configured in preferences
361	        auto &p = Preferences::getInstance();
362	        if(p.Acquisition.limitDFT) {
363	            std::this_thread::sleep_until(lastCalc + duration<double>(1.0 / p.Acquisition.maxDFTrate));
364	            lastCalc = system_clock::now();
365	        }
366	    }
367	}
