namespace Math {

class TDR;

class TDRThread : public QThread
{
    Q_OBJECT
public:
    TDRThread(TDR &tdr);
    ~TDRThread(){}
private:
    void run() override;
    TDR &tdr;
};

class TDR : public TraceMath
{
