193	            qDebug() << "DFT thread exiting";
194	            return;
195	        }
196	        // qDebug() << "DFT thread calculating";
197	        if(!dft.input) {
198	            // not connected, skip calculation
199	            continue;
200	        }
201	        auto inputData = dft.input->getData();
202	        if(!inputData.size()) {
203	            dft.clearOutput();
204	            dft.warning("Not enough input samples");
205	            continue;
206	        }
207	
208	        double DC = dft.DCfreq;
209	        TDR *tdr = nullptr;
210	        // find the last TDR operation
211	        auto in = dft.input;
212	        while(in->getType() != DFT::Type::TDR) {
213	            in = dft.input->getInput();
214	            if(!in) {
215	                break;
216	            }
217	        }
218	        if(in) {
219	            tdr = static_cast<TDR*>(in);
220	        }
221	
222	        if(tdr && dft.automaticDC) {
223	            if(tdr->getMode() == TDR::Mode::Lowpass) {
224	                DC = 0;
225	            } else {
226	                // bandpass mode, assume DC is in the middle of the frequency data
227	                DC = tdr->getInput()->getSample(tdr->getInput()->numSamples()/2).x;
228	            }
229	        }
230	        auto samples = inputData.size();
231	        auto timeSpacing = inputData[1].x - inputData[0].x;
232	        vector<complex<double>> timeDomain(samples);
233	        for(unsigned int i=0;i<samples;i++) {
234	            timeDomain.at(i) = inputData[i].y;
235	        }
236	
237	        dft.window.apply(timeDomain);
238	        Fft::shift(timeDomain, true);
239	        Fft::transform(timeDomain, false);
240	        // shift DC bin into the middle
241	        Fft::shift(timeDomain, false);
242	
243	        double binSpacing = 1.0 / (timeSpacing * timeDomain.size());
244	
245	        if(tdr) {
246	            // split in padding and actual data sections
247	            unsigned int padding = 0;
248	            if(timeDomain.size() > tdr->getUnpaddedInputSize()) {
249	                padding = timeDomain.size() - tdr->getUnpaddedInputSize();
250	            }
251	            std::vector<std::complex<double>> pad_front(timeDomain.begin(), timeDomain.begin()+padding/2);
252	            std::vector<std::complex<double>> data(timeDomain.begin()+padding/2, timeDomain.end()-padding/2);
253	            std::vector<std::complex<double>> pad_back(timeDomain.end()-padding/2, timeDomain.end());
254	
255	            if(dft.revertWindowFromTDR) {
256	                tdr->getWindow().reverse(data);
257	            }
258	
259	            if(dft.removePaddingFromTDR) {
260	                timeDomain = data;
261	            } else {
262	                // include padding
263	                timeDomain = pad_front;
264	                copy(data.begin(), data.end(), back_inserter(timeDomain));
265	                copy(pad_back.begin(), pad_back.end(), back_inserter(timeDomain));
266	            }
267	        }
268	
269	        int DCbin = timeDomain.size() / 2, startBin = 0;
270	        dft.dataMutex.lock();
271	        if(DC > 0) {
272	            dft.data.resize(timeDomain.size(), TraceMath::Data());
273	        } else {
274	            startBin = (timeDomain.size()+1) / 2;
275	            dft.data.resize(timeDomain.size()/2, TraceMath::Data());
276	        }
277	
278	        for(int i = startBin;(unsigned int) i<timeDomain.size();i++) {
279	            auto freq = (i - DCbin) * binSpacing + DC;
280	            dft.data[i - startBin].x = round(freq);
281	            dft.data[i - startBin].y = timeDomain.at(i);
