245	void Math::TimeGate::updateFilter()
246	{
247	    if(!input) {
248	        return;
249	    }
250	    auto inputData = input->getData();
251	    std::vector<std::complex<double>> buf;
252	    filter.clear();
253	    buf.resize(inputData.size() * 2);
254	    if(!buf.size()) {
255	        return;
256	    }
257	    auto maxX = inputData.back().x;
258	    auto minX = inputData.front().x;
259	
260	    auto wc1 = Util::Scale<double>(center - span / 2, minX, maxX, 0, 1);
261	    auto wc2 = Util::Scale<double>(center + span / 2, minX, maxX, 0, 1);
262	
263	    // create ideal filter coefficients
264	    for(unsigned int i=0;i<buf.size();i++) {
265	        int n = i - buf.size() / 2;
266	        if(n == 0) {
267	            buf[i] = wc2 - wc1;
268	        } else {
269	            buf[i] = (sin(M_PI * wc2 * n) - sin(M_PI * wc1 * n)) / (n * M_PI);
270	        }
271	        if(!bandpass) {
272	            if(n == 0) {
273	                buf[i] = 1.0 - buf[i];
274	            } else {
275	                buf[i] = sin(M_PI * n) / M_PI - buf[i];
276	            }
277	        }
278	    }
279	
280	    window.apply(buf);
281	    Fft::shift(buf, true);
282	    Fft::transform(buf, false);
283	
284	    filter.resize(buf.size() / 2);
285	    for(unsigned int i=0;i<buf.size() / 2;i++) {
286	        filter[i] = abs(buf[i]);
287	    }
288	    emit filterUpdated();
289	
290	    // needs to update output samples, pretend that input samples have changed
291	    inputSamplesChanged(0, inputData.size());
292	}
