355	void Math::TimeGateGraph::paintEvent(QPaintEvent *event)
356	{
357	    if(!gate || !gate->getInput()) {
358	        return;
359	    }
360	    // grab input data
361	    auto inputData = gate->getInput()->getData();
362	
363	    Q_UNUSED(event)
364	    auto& pref = Preferences::getInstance();
365	    QPainter p(this);
366	    // fill background
367	    p.setBackground(QBrush(pref.Graphs.Color.background));
368	    p.fillRect(0, 0, width(), height(), QBrush(pref.Graphs.Color.background));
369	
370	    if(!inputData.size()) {
371	        // no data yet, nothing to plot
372	        return;
373	    }
374	
375	    // plot trace
376	    auto pen = QPen(Qt::green, 1);
377	    pen.setCosmetic(true);
378	    pen.setStyle(Qt::SolidLine);
379	    p.setPen(pen);
380	
381	    auto minX = inputData.front().x;
382	    auto maxX = inputData.back().x;
383	
384	    int plotLeft = 0;
385	    int plotRight = size().width();
386	    int plotTop = 0;
387	    int plotBottom = size().height();
388	
389	    QPoint p1, p2;
390	
391	    // limit amount of displayed points to keep GUI snappy
392	    auto increment = inputData.size() / 500;
393	    if(!increment) {
394	        increment = 1;
395	    }
396	
397	    for(unsigned int i=increment;i<inputData.size();i+=increment) {
398	        auto last = inputData[i-increment];
399	        auto now = inputData[i];
400	
401	        auto y_last = Util::SparamTodB(last.y);
402	        auto y_now = Util::SparamTodB(now.y);
403	
404	        if(std::isnan(y_last) || std::isnan(y_now) || std::isinf(y_last) || std::isinf(y_now)) {
405	            continue;
406	        }
407	
408	        // scale to plot coordinates
409	        p1.setX(Util::Scale<double>(last.x, minX, maxX, plotLeft, plotRight));
410	        p1.setY(Util::Scale<double>(y_last, -120, 20, plotBottom, plotTop));
411	        p2.setX(Util::Scale<double>(now.x, minX, maxX, plotLeft, plotRight));
412	        p2.setY(Util::Scale<double>(y_now, -120, 20, plotBottom, plotTop));
413	        // draw line
414	        p.drawLine(p1, p2);
415	    }
416	    // plot filter shape
417	    auto filter = gate->rFilter();
418	    pen = QPen(Qt::red, 1);
419	    p.setPen(pen);
420	    for(unsigned int i=increment;i<filter.size() && i<inputData.size();i+=increment) {
421	        auto x_last = inputData[i-increment].x;
422	        auto x_now = inputData[i].x;
423	
424	        auto f_last = Util::SparamTodB(filter[i-increment]);
425	        auto f_now = Util::SparamTodB(filter[i]);
426	
427	        if(std::isnan(f_last) || std::isnan(f_now) || std::isinf(f_last) || std::isinf(f_now)) {
428	            continue;
429	        }
430	
431	        // scale to plot coordinates
432	        p1.setX(Util::Scale<double>(x_last, minX, maxX, plotLeft, plotRight));
433	        p1.setY(Util::Scale<double>(f_last, -120, 20, plotBottom, plotTop));
434	        p2.setX(Util::Scale<double>(x_now, minX, maxX, plotLeft, plotRight));
435	        p2.setY(Util::Scale<double>(f_now, -120, 20, plotBottom, plotTop));
436	        // draw line
437	        p.drawLine(p1, p2);
438	    }
439	}
