28	#include <cstdint>
29	#include <stdexcept>
30	#include <utility>
31	#include <algorithm>
32	
33	using std::complex;
34	using std::size_t;
35	using std::uintmax_t;
36	using std::vector;
37	
38	
39	// Private function prototypes
40	static size_t reverseBits(size_t val, int width);
41	
42	
43	void Fft::transform(vector<complex<double> > &vec, bool inverse) {
44	    size_t n = vec.size();
45	    if (n == 0)
46	        return;
47	    else if ((n & (n - 1)) == 0)  // Is power of 2
48	        transformRadix2(vec, inverse);
49	    else  // More complicated algorithm for arbitrary sizes
50	        transformBluestein(vec, inverse);
51	}
52	
53	
54	void Fft::transformRadix2(vector<complex<double> > &vec, bool inverse) {
55	    // Length variables
56	    size_t n = vec.size();
57	    int levels = 0;  // Compute levels = floor(log2(n))
58	    for (size_t temp = n; temp > 1U; temp >>= 1)
59	        levels++;
60	    if (static_cast<size_t>(1U) << levels != n)
61	        throw std::domain_error("Length is not a power of 2");
62	
63	    // Trigonometric table
64	    vector<complex<double> > expTable(n / 2);
65	    for (size_t i = 0; i < n / 2; i++)
66	        expTable[i] = std::polar(1.0, (inverse ? 2 : -2) * M_PI * i / n);
67	
68	    // Bit-reversed addressing permutation
69	    for (size_t i = 0; i < n; i++) {
70	        size_t j = reverseBits(i, levels);
71	        if (j > i)
72	            std::swap(vec[i], vec[j]);
73	    }
74	
75	    // Cooley-Tukey decimation-in-time radix-2 FFT
76	    for (size_t size = 2; size <= n; size *= 2) {
77	        size_t halfsize = size / 2;
78	        size_t tablestep = n / size;
79	        for (size_t i = 0; i < n; i += size) {
80	            for (size_t j = i, k = 0; j < i + halfsize; j++, k += tablestep) {
81	                complex<double> temp = vec[j + halfsize] * expTable[k];
82	                vec[j + halfsize] = vec[j] - temp;
83	                vec[j] += temp;
84	            }
85	        }
86	        if (size == n)  // Prevent overflow in 'size *= 2'
87	            break;
88	    }
89	}
90	
91	
92	void Fft::transformBluestein(vector<complex<double> > &vec, bool inverse) {
93	    // Find a power-of-2 convolution length m such that m >= n * 2 + 1
94	    size_t n = vec.size();
95	    size_t m = 1;
96	    while (m / 2 <= n) {
97	        if (m > SIZE_MAX / 2)
98	            throw std::length_error("Vector too large");
99	        m *= 2;
100	    }
101	
102	    // Trigonometric table
103	    vector<complex<double> > expTable(n);
104	    for (size_t i = 0; i < n; i++) {
105	        uintmax_t temp = static_cast<uintmax_t>(i) * i;
106	        temp %= static_cast<uintmax_t>(n) * 2;
107	        double angle = (inverse ? M_PI : -M_PI) * temp / n;
108	        expTable[i] = std::polar(1.0, angle);
109	    }
110	
111	    // Temporary vectors and preprocessing
112	    vector<complex<double> > avec(m);
113	    for (size_t i = 0; i < n; i++)
114	        avec[i] = vec[i] * expTable[i];
115	    vector<complex<double> > bvec(m);
116	    bvec[0] = expTable[0];
117	    for (size_t i = 1; i < n; i++)
118	        bvec[i] = bvec[m - i] = std::conj(expTable[i]);
119	
120	    // Convolution
121	    vector<complex<double> > cvec(m);
122	    convolve(avec, bvec, cvec);
123	
124	    // Postprocessing
125	    for (size_t i = 0; i < n; i++)
126	        vec[i] = cvec[i] * expTable[i];
127	}
128	
129	
130	void Fft::convolve(
131	        const vector<complex<double> > &xvec,
132	        const vector<complex<double> > &yvec,
133	        vector<complex<double> > &outvec) {
134	
135	    size_t n = xvec.size();
136	    if (n != yvec.size() || n != outvec.size())
137	        throw std::domain_error("Mismatched lengths");
